from lib import *
S = SS('u120')
steps = [
    step("unsafe 只多出五种能力。没有 unsafe 时逐个编译失败:解引用裸指针 → error[E0133]: dereference of raw pointer is unsafe and requires unsafe block;调用 unsafe fn → E0133 call to unsafe function `danger`;访问 static mut → E0133 use of mutable static;访问 union 字段 → E0133 access to union field。", t=tl(S(1)), done=lidx(S(1), '解引用裸指针', '调用 unsafe 函数', '访问 static mut', '访问 union 字段'), kv=KV([['裸指针解引用', 'E0133'], ['调用 unsafe fn', 'E0133'], ['static mut', 'E0133'], ['union 字段', 'E0133']], ['union 字段'])),
    step("第五种:实现 unsafe trait。不写 unsafe 就 impl Zeroable for S,报 error[E0200]: the trait `Zeroable` requires an `unsafe impl` declaration,note 说「enforces invariants that the compiler can't check」。", t=tl(S(1)), mark=lidx(S(1), 'error[E0200]', "invariants"), kv=KV([['impl unsafe trait', 'E0200:要写 unsafe impl']], ['impl unsafe trait'])),
    step("放进 unsafe 块之后五种都能编译运行:*p = 5、read(p) = 5、static mut N 加一后为 1、union 把 u32 0x3f800000 当 f32 读得 1、unsafe impl Zeroable for u32 编译通过。unsafe 块是程序员对编译器的承诺:「这里的前提条件我已经保证了」。", t=tl(S(2)), done=lidx(S(2), '解引用裸指针', '调用 unsafe fn', 'static mut N', 'union 字段 b', 'unsafe impl'), kv=KV([['unsafe { }', '承诺前提条件已满足']], ['unsafe { }'])),
    step("unsafe 不会关掉借用检查器:unsafe { v.push(2) } 时有一个 &v[0] 还活着,照样报 error[E0502]: cannot borrow `v` as mutable because it is also borrowed as immutable(并警告「unnecessary `unsafe` block」—— 这里根本不需要 unsafe)。", t=tl(S(3)), mark=lidx(S(3), 'error[E0502]', 'unnecessary `unsafe` block'), kv=KV([['unsafe 块里', '借用规则照常检查']], ['unsafe 块里'])),
    step("安全抽象:用 unsafe 写一个 my_split_at_mut,对外是安全函数:assert!(mid <= len) 是 unsafe 块成立的前提;正常调用得到 [10, 2, 30, 4, 5];传 99 越界时 assert 触发 panic「mid 必须 <= 长度」(退出码 101),而不是未定义行为。unsafe 要缩到最小,把前提条件检查放在它前面。", t=tl(S(4)), done=lidx(S(4), '安全接口的结果'), mark=lidx(S(4), 'mid 必须'), kv=KV([['unsafe 块', '最小范围'], ['前提条件', 'assert 先检查,越界 panic']], ['前提条件'])),
    step("#![forbid(unsafe_code)] 让整个 crate 禁止 unsafe:写了 unsafe 块就报 error: usage of an `unsafe` block,note 指向 forbid 所在行。另外 2024 edition 里 unsafe fn 的函数体不再自动是 unsafe 块:fn f 里直接 *p 会警告 E0133(unsafe_op_in_unsafe_fn),note 说「an unsafe function restricts its caller, but its body is safe by default」。", t=tl(S(5)), mark=lidx(S(5), 'usage of an `unsafe` block', 'unsafe_op_in_unsafe_fn'), kv=KV([['forbid(unsafe_code)', '整个 crate 不许 unsafe'], ['unsafe fn 内部', '2024 起要再写 unsafe 块']], ['forbid(unsafe_code)'])),
]
A = mkart('u120', 120, 'Rust,unsafe,安全边界,E0133,真实验证,动画演示',
    '用真实编译验证 unsafe 的边界:只多出五种能力(裸指针解引用、unsafe fn、static mut、union 字段都报 E0133,实现 unsafe trait 报 E0200);放进 unsafe 块全部通过;unsafe 不关借用检查(E0502);用 unsafe 实现带 assert 的安全 split_at_mut;#![forbid(unsafe_code)] 与 2024 edition 的 unsafe_op_in_unsafe_fn。',
    'unsafe 到底解锁了什么?它有没有关掉借用检查?怎么把 unsafe 封装成安全接口?这篇逐条编译验证 unsafe 的边界,并写一个最小的安全抽象示范「前提条件检查 + 最小 unsafe 块」。',
    [('5 种', 'unsafe 解锁的能力数(裸指针、unsafe fn、static mut、unsafe trait、union)'), ('E0133', '在 unsafe 块外使用这些能力时的错误码'), ('E0502', 'unsafe 块里仍然会被借用检查器拒绝的错误')],
    [('五种超能力', '<p>裸指针的使用见<a href="rust-raw-pointer-deref.html">原始指针解引用</a>。</p>'), ('放进 unsafe 块', None), ('借用检查仍然有效', '<p>借用规则见<a href="rust-shared-vs-mut-borrow.html">不可变借用与可变借用</a>。</p>'), ('安全抽象', None), ('forbid 与 2024 edition', '<p>跨线程的 unsafe impl 见<a href="rust-send-sync.html">Send 与 Sync</a>。</p>')],
    steps, [ENV_U, '没有验证:Miri 检查 unsafe 代码(需要 nightly)、unsafe 代码里的未定义行为的实际后果、extern 块里 unsafe 的写法在其它 edition 的差别、cargo-geiger 之类统计 unsafe 的工具'], 'unsafe 的边界')
